import { requireSupabase } from '@/lib/supabase/client'
import type { GroupRole, StudyGroup } from '@/types'

/**
 * Study groups, membership and invitations.
 *
 * Every privileged action is a SECURITY DEFINER RPC, not a direct table write:
 *
 *  * invitation codes are generated by Postgres (`gen_random_bytes`), so a
 *    client cannot choose or predict one;
 *  * the "keep at least one owner" invariant is enforced server-side;
 *  * role changes require owner, and an admin cannot promote anyone to owner.
 *
 * The client hides controls the caller cannot use, but that is a usability
 * measure only — the functions reject unauthorised calls regardless.
 */

export class GroupError extends Error {
  readonly cause?: unknown
  constructor(message: string, cause?: unknown) {
    super(message)
    this.name = 'GroupError'
    this.cause = cause
  }
}

export type GroupMember = {
  user_id: string
  role: GroupRole
  joined_at: string
  display_name: string | null
  username: string | null
  avatar_url: string | null
}

export type Invitation = {
  id: string
  group_id: string
  code: string
  expires_at: string | null
  max_uses: number | null
  uses: number
  revoked_at: string | null
  created_at: string
}

export type GroupWithRole = StudyGroup & {
  role: GroupRole
  memberCount: number
}

/** Postgres error codes we can turn into a useful sentence. */
function describe(message: string): string {
  if (/only owner/i.test(message)) return 'Only a group owner can do that.'
  if (/only a group owner or admin/i.test(message)) return 'Only an owner or admin can do that.'
  if (/at least one owner/i.test(message)) return 'A group must keep at least one owner.'
  if (/your own role/i.test(message)) return 'You cannot change your own role.'
  if (/expired/i.test(message)) return 'This invitation code has expired.'
  if (/invalid or expired/i.test(message)) return 'This invitation code is not valid.'
  if (/not a member/i.test(message)) return 'You are not a member of this group.'
  if (/already/i.test(message)) return 'You are already a member of this group.'
  return message
}

async function rpc<T>(name: string, args: Record<string, unknown>): Promise<T> {
  const sb = requireSupabase()
  const { data, error } = await sb.rpc(name, args)
  if (error) throw new GroupError(describe(error.message), error)
  return data as T
}

// ---------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------

export async function fetchMyGroups(): Promise<GroupWithRole[]> {
  const sb = requireSupabase()
  const { data, error } = await sb
    .from('study_group_members')
    .select('group_id, role, study_groups(id, name, description, visibility, share_progress, created_by, created_at)')
  if (error) throw new GroupError(error.message, error)

  return (data ?? []).flatMap((row) => {
    // PostgREST returns an embedded relation as an array when it cannot prove
    // the cardinality is one-to-one.
    const embedded = row.study_groups
    const group = (Array.isArray(embedded) ? embedded[0] : embedded) as StudyGroup | null
    if (!group) return []
    return [{ ...group, role: row.role as GroupRole, memberCount: 0 }]
  })
}

export async function fetchMembers(groupId: string): Promise<GroupMember[]> {
  const sb = requireSupabase()

  // Two queries rather than one PostgREST embed: `profiles_public` is a VIEW,
  // so there is no foreign key for PostgREST to disambiguate an embedded
  // select against it.
  const { data, error } = await sb
    .from('study_group_members')
    .select('user_id, role, joined_at')
    .eq('group_id', groupId)
  if (error) throw new GroupError(error.message, error)

  const rows = data ?? []
  const ids = rows.map((row) => row.user_id as string)

  // profiles_public exposes only the non-sensitive columns and applies the
  // same visibility rules as the table policies.
  let byId = new Map<string, { username: string | null; display_name: string | null; avatar_url: string | null }>()
  if (ids.length > 0) {
    const { data: profiles, error: profileError } = await sb
      .from('profiles_public')
      .select('id, username, display_name, avatar_url')
      .in('id', ids)
    if (profileError) throw new GroupError(profileError.message, profileError)
    byId = new Map(
      (profiles ?? []).map((p) => [
        p.id as string,
        {
          username: p.username as string | null,
          display_name: p.display_name as string | null,
          avatar_url: p.avatar_url as string | null,
        },
      ]),
    )
  }

  return rows.map((row) => ({
    user_id: row.user_id as string,
    role: row.role as GroupRole,
    joined_at: row.joined_at,
    display_name: byId.get(row.user_id as string)?.display_name ?? null,
    username: byId.get(row.user_id as string)?.username ?? null,
    avatar_url: byId.get(row.user_id as string)?.avatar_url ?? null,
  }))
}

/**
 * Invitations are only readable by owners and admins — the table has no select
 * policy for ordinary members, so a plain member gets an empty list rather than
 * the codes.
 */
export async function fetchInvitations(groupId: string): Promise<Invitation[]> {
  const sb = requireSupabase()
  const { data, error } = await sb
    .from('group_invitations')
    .select('id, group_id, code, expires_at, max_uses, uses, revoked_at, created_at')
    .eq('group_id', groupId)
    .order('created_at', { ascending: false })
  if (error) throw new GroupError(error.message, error)
  return (data ?? []) as Invitation[]
}

// ---------------------------------------------------------------------------
// Writes (all privileged operations are server-side functions)
// ---------------------------------------------------------------------------

export async function createGroup(input: {
  name: string
  description?: string | null
  visibility: 'private' | 'group'
}): Promise<string> {
  return rpc<string>('create_study_group', {
    p_name: input.name,
    p_description: input.description ?? null,
    p_visibility: input.visibility,
  })
}

/** Redeem an invitation code. Always joins as `member` — never owner/admin. */
export async function joinWithCode(code: string): Promise<string> {
  return rpc<string>('redeem_group_invitation', { p_code: code.trim() })
}

export async function createInvitation(
  groupId: string,
  options: { expiresDays?: number | null; maxUses?: number | null } = {},
): Promise<Invitation> {
  return rpc<Invitation>('create_group_invitation', {
    p_group_id: groupId,
    p_expires_days: options.expiresDays ?? 7,
    p_max_uses: options.maxUses ?? null,
  })
}

export async function revokeInvitation(invitationId: string): Promise<void> {
  await rpc<void>('revoke_group_invitation', { p_invitation_id: invitationId })
}

export async function leaveGroup(groupId: string): Promise<void> {
  await rpc<void>('leave_group', { p_group_id: groupId })
}

export async function removeMember(groupId: string, userId: string): Promise<void> {
  await rpc<void>('remove_group_member', { p_group_id: groupId, p_user_id: userId })
}

export async function changeMemberRole(
  groupId: string,
  userId: string,
  role: GroupRole,
): Promise<void> {
  await rpc<void>('change_member_role', {
    p_group_id: groupId,
    p_user_id: userId,
    p_role: role,
  })
}